const { execFileSync } = await import('node:child_process');
const { mkdtempSync, existsSync, rmSync } = await import('node:fs');
const { tmpdir } = await import('node:os');
const { join } = await import('node:path');
const tempDir = mkdtempSync(join(tmpdir(), 'koala-codex-init-'));
try {
  const out = execFileSync('node', ['packages/main/dist/cli.js', 'init', tempDir], { cwd: $root, encoding: 'utf8' });
  return {
    mentionsAgents: out.includes('.Codex/agents/test-intent.md'),
    mentionsReadme: out.includes('.Codex/README.md'),
    hasAgents: existsSync(join(tempDir, '.Codex', 'agents', 'test-intent.md')),
    hasReviewer: existsSync(join(tempDir, '.Codex', 'agents', 'test-case-reviewer.md')),
    hasReadme: existsSync(join(tempDir, '.Codex', 'README.md')),
    hasAgentsMd: existsSync(join(tempDir, 'AGENTS.md')),
  };
} finally {
  rmSync(tempDir, { recursive: true, force: true });
}

const { execFileSync } = await import('node:child_process');
const { mkdtempSync, writeFileSync, readFileSync, rmSync, unlinkSync, existsSync } = await import('node:fs');
const { tmpdir } = await import('node:os');
const { join } = await import('node:path');
const tempDir = mkdtempSync(join(tmpdir(), 'koala-codex-rerun-'));
try {
  execFileSync('node', ['packages/main/dist/cli.js', 'init', tempDir], { cwd: $root, encoding: 'utf8' });
  const readmePath = join(tempDir, '.Codex', 'README.md');
  writeFileSync(readmePath, '# custom codex readme\n');
  unlinkSync(join(tempDir, '.Codex', 'agents', 'test-case-reviewer.md'));
  const second = execFileSync('node', ['packages/main/dist/cli.js', 'init', tempDir], { cwd: $root, encoding: 'utf8' });
  return {
    skippedExisting: second.includes('.Codex/README.md (exists, skip)'),
    restoredMissing: existsSync(join(tempDir, '.Codex', 'agents', 'test-case-reviewer.md')),
    preservedCustom: readFileSync(readmePath, 'utf8').includes('custom codex readme')
  };
} finally {
  rmSync(tempDir, { recursive: true, force: true });
}

const { execFileSync } = await import('node:child_process');
const { mkdtempSync, existsSync, rmSync } = await import('node:fs');
const { tmpdir } = await import('node:os');
const { join } = await import('node:path');
const tempDir = mkdtempSync(join(tmpdir(), 'koala-codex-doublecheck-'));
try {
  const repoCheck = execFileSync('npm', ['run', 'test:codex-assets'], { cwd: $root, encoding: 'utf8' });
  execFileSync('node', ['packages/main/dist/cli.js', 'init', tempDir], { cwd: $root, encoding: 'utf8' });
  return {
    repoCheckPasses: repoCheck.includes('codex assets verified'),
    initProducesAssets: existsSync(join(tempDir, '.Codex', 'agents', 'test-intent.md')) && existsSync(join(tempDir, '.Codex', 'README.md'))
  };
} finally {
  rmSync(tempDir, { recursive: true, force: true });
}

const { execFileSync } = await import('node:child_process');
const out = execFileSync('npm', ['run', 'test:codex-assets'], { cwd: $root, encoding: 'utf8' });
return { ok: out.includes('codex assets verified') };

const mod = await import(new URL('file://' + $root + '/packages/main/dist/init-assets.js').href);
const sample = 'Claude Code uses .claude/agents/test-intent.md';
const out = mod.renderCodexAgentContent(sample);
return {
  renamedPlatform: out.includes('Codex uses'),
  renamedPath: out.includes('.Codex/agents/test-intent.md')
};

const { execFileSync } = await import('node:child_process');
const { appendFileSync, readFileSync, writeFileSync } = await import('node:fs');
const { join } = await import('node:path');
const target = join($root, '.Codex', 'agents', 'test-intent.md');
const original = readFileSync(target, 'utf8');
appendFileSync(target, '\n<!-- drift -->\n');
try {
  execFileSync('node', ['scripts/verify-codex-assets.mjs'], { cwd: $root, encoding: 'utf8', stdio: 'pipe' });
  return { driftCaught: false, mentionsDrift: false };
} catch (error) {
  const text = String(error.stderr || error.stdout || error.message || error);
  return {
    driftCaught: text.includes('drifted from transformed .claude source'),
    mentionsDrift: text.includes('.Codex/agents/test-intent.md')
  };
} finally {
  writeFileSync(target, original);
}

const { readFileSync } = await import('node:fs');
const { join } = await import('node:path');
const readme = readFileSync(join($root, 'README.md'), 'utf8');
const codex = readFileSync(join($root, '.Codex', 'README.md'), 'utf8');
const agents = readFileSync(join($root, 'AGENTS.md'), 'utf8');
return {
  readmeHasWrapper: readme.includes('node bin/koala-codex.js session_brief'),
  codexHasFallback: codex.includes('KOALA_ACTIVITY_SOURCE=codex koala session_brief'),
  agentsHasSessionBrief: agents.includes('koala session_brief')
};

