const { execFileSync } = await import('node:child_process');
const { readFileSync, writeFileSync } = await import('node:fs');
const { join } = await import('node:path');
const target = join($root, '.Codex', 'README.md');
const original = readFileSync(target, 'utf8');
const broken = original.split('KOALA_ACTIVITY_SOURCE=codex koala session_brief').join('koala session_brief');
writeFileSync(target, broken);
try {
  execFileSync('node', ['scripts/verify-codex-assets.mjs'], { cwd: $root, encoding: 'utf8', stdio: 'pipe' });
  return { driftCaught: false, mentionsFallback: false };
} catch (error) {
  const text = String(error.stderr || error.stdout || error.message || error);
  return {
    driftCaught: text.includes('.Codex/README missing fallback command'),
    mentionsFallback: text.includes('fallback command')
  };
} finally {
  writeFileSync(target, original);
}
